**`CheckoutPage.tsx`**
```tsx
import React, { useMemo, useState } from "react";
import { CartItem, DeliveryAddress } from "./types";
import "./CheckoutPage.css";

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  street: "",
  houseNumber: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatPrice(value: number): string {
  return value.toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = "Full name is required.";
  if (!address.street.trim()) errors.street = "Street is required.";
  if (!address.houseNumber.trim()) errors.houseNumber = "House number is required.";
  if (!address.city.trim()) errors.city = "City is required.";
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  } else if (!/^[A-Za-z0-9\- ]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code.";
  }
  if (!address.country.trim()) errors.country = "Country is required.";
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[+0-9\s-]{7,20}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  return errors;
}

export default function CheckoutPage({ items, onBackToCart, onPay }: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const shipping = items.length > 0 ? 4.99 : 0;
  const total = subtotal + shipping;

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    setIsSubmitting(true);
    onPay(address);
  };

  const isCartEmpty = items.length === 0;

  return (
    <div className="checkout-page">
      <h1 className="checkout-title">Checkout</h1>

      <div className="checkout-layout">
        <section className="checkout-section" aria-labelledby="cart-heading">
          <h2 id="cart-heading" className="section-heading">
            Your items
          </h2>

          {isCartEmpty ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {items.map((item) => (
                <li className="cart-item" key={item.id}>
                  <img
                    className="cart-item-image"
                    src={item.imageUrl}
                    alt={item.name}
                  />
                  <div className="cart-item-info">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="summary">
            <div className="summary-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="summary-row">
              <span>Shipping</span>
              <span>{formatPrice(shipping)}</span>
            </div>
            <div className="summary-row summary-total">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>

          <button
            type="button"
            className="btn btn-secondary"
            onClick={onBackToCart}
          >
            Back to cart
          </button>
        </section>

        <section className="checkout-section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="section-heading">
            Delivery address
          </h2>

          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleChange("fullName")}
                aria-invalid={!!errors.fullName}
                aria-describedby={errors.fullName ? "fullName-error" : undefined}
              />
              {errors.fullName && (
                <span className="field-error" id="fullName-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field form-field-grow">
                <label htmlFor="street">Street</label>
                <input
                  id="street"
                  type="text"
                  value={address.street}
                  onChange={handleChange("street")}
                  aria-invalid={!!errors.street}
                  aria-describedby={errors.street ? "street-error" : undefined}
                />
                {errors.street && (
                  <span className="field-error" id="street-error">
                    {errors.street}
                  </span>
                )}
              </div>

              <div className="form-field form-field-small">
                <label htmlFor="houseNumber">No.</label>
                <input
                  id="houseNumber"
                  type="text"
                  value={address.houseNumber}
                  onChange={handleChange("houseNumber")}
                  aria-invalid={!!errors.houseNumber}
                  aria-describedby={
                    errors.houseNumber ? "houseNumber-error" : undefined
                  }
                />
                {errors.houseNumber && (
                  <span className="field-error" id="houseNumber-error">
                    {errors.houseNumber}
                  </span>
                )}
              </div>
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleChange("postalCode")}
                  aria-invalid={!!errors.postalCode}
                  aria-describedby={
                    errors.postalCode ? "postalCode-error" : undefined
                  }
                />
                {errors.postalCode && (
                  <span className="field-error" id="postalCode-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>

              <div className="form-field form-field-grow">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleChange("city")}
                  aria-invalid={!!errors.city}
                  aria-describedby={errors.city ? "city-error" : undefined}
                />
                {errors.city && (
                  <span className="field-error" id="city-error">
                    {errors.city}
                  </span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleChange("country")}
                aria-invalid={!!errors.country}
                aria-describedby={errors.country ? "country-error" : undefined}
              />
              {errors.country && (
                <span className="field-error" id="country-error">
                  {errors.country}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleChange("phone")}
                aria-invalid={!!errors.phone}
                aria-describedby={errors.phone ? "phone-error" : undefined}
              />
              {errors.phone && (
                <span className="field-error" id="phone-error">
                  {errors.phone}
                </span>
              )}
            </div>

            <button
              type="submit"
              className="btn btn-primary"
              disabled={isCartEmpty || isSubmitting}
            >
              {isSubmitting ? "Processing…" : `Pay ${formatPrice(total)}`}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
}
```

