    unitPrice: 12.5,
    quantity: 2,
  },
];

export default function App() {
  const handleBackToCart = () => {
    // navigate back to the cart page
  };

  const handlePay = (address: DeliveryAddress) => {
    // submit order + address to the backend
    console.log("Paying with address:", address);
  };

  return (
